var seed = Math.random() * 2000;
var particles = [];
var mySize;
var parNum;
var color_vision;

function setup() {
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight);
	createCanvas(windowWidth, windowHeight);
	colorMode(RGB, 255, 255, 255, 100);
	// pixelDensity(5);
	background("#fff");
	parNum = 2000;
	for (let i = 0; i < parNum; i++) {
		particles.push(new Particle(random(width),height / 2 - tan(random(1,2) * i + random(50)) * height / 30));
	}
	color_vision = random([1, 2, 3, 4, 5])
}

function draw() {
  // === Variant 3: Fractal Orbit Matrix ===
  gridOffset = noise(frameCount * 0.01) * 80;
  push();
  translate(gridOffset, -gridOffset);

	blendMode(BLEND);
	// background("#20202033");
	// blendMode(ADD);
	for (let i = particles.length - 1; i > 0; i--) {
		if (i < particles.length) {
			if (int(seed) % 2 == 0) {
				particles[i].color_vision = color_vision;
			}
			particles[i].update();
			particles[i].show();
			if (particles[i].alpha2 < 30) {
				particles[i].explode();
			}
			if (particles[i].finished()) {
				particles.splice(i, 1);
				seed = Math.random() * 1000;
				color_vision = random([1, 2, 3, 4, 5])
				//particles.push(new Particle(width / 2 - tan(random(1,5) * i + random(50)) * width / 4 , random(height)));
			}
		}
	}

  pop();
}

